mapper.select:

ORDER BY i.created_at ASC,i.id ASC
ORDER BY i.created_at DESC,i.id DESC
LIMIT 20 OFFSET #{offset}

mapper.update:
UPDATE inquiries SET answer=#{answer},status='ANSWERED',answered_by=#{adminId},answered_at=CURRENT_TIMESTAMP,
version=version+1,ai_token=NULL,ai_state=CASE WHEN ai_state='RUNNING' THEN 'CANCELLED' ELSE ai_state END
WHERE id=#{id} AND version=#{version}
